// and the C entry points pow, asin, acos, fmod, their dispatchers (__trandisp1/2, __ctrandisp1/2,
// __cintrindisp1/2), argument loaders (__fload, __fload_withFB), the error exits (__startOneArgErrorHandling,
// __math_exit and their variants), the Pentium fprem workaround and the five small functions of ieee87.c/frnd.c
// that are inline assembly in C (_frnd, _statfp, _clrfp, _ctrlfp, _set_statfp).
//
// Generated by tools/crt_asm_gen.py from the exe's code (docs/DECOMPILATION.md 11, "C runtime, phase 5b"):
// the same instructions as the original (assembly in VC6's runtime sources too; the results depend on
// the exact x87 sequence), branches between them as labels, calls and jumps out of them through
// pointers to the exe's entry points (hooked where reimplemented), copied descriptors with the
// handlers replaced by the labels. Data stays in the exe. The generator assembles the module and
// checks every unchanged instruction against the original bytes. Each instruction carries the
// address of its original.
#include "reimpl.h"

